"""Exercise the actual CreatureRig builder/animation with a small geometry harness.
This does not substitute for Minecraft model baking or a graphical playtest.
Requires JDK 21. Optional argument: output JSON for the geometry preview.
"""
from pathlib import Path
import tempfile,subprocess,re,sys
ROOT=Path(__file__).resolve().parents[1]
def write(root,path,source):
 p=root/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(source)
with tempfile.TemporaryDirectory() as temp:
 t=Path(temp)
 write(t,'net/minecraft/util/Mth.java','''package net.minecraft.util;public class Mth{public static final float PI=(float)Math.PI,DEG_TO_RAD=PI/180;public static float sin(float x){return (float)Math.sin(x);}public static float cos(float x){return (float)Math.cos(x);}public static float clamp(float x,float a,float b){return Math.clamp(x,a,b);}}''')
 write(t,'net/minecraft/client/model/geom/PartPose.java','''package net.minecraft.client.model.geom;public record PartPose(float x,float y,float z,float xr,float yr,float zr){public static final PartPose ZERO=offset(0,0,0);public static PartPose offset(float x,float y,float z){return new PartPose(x,y,z,0,0,0);}public static PartPose offsetAndRotation(float x,float y,float z,float xr,float yr,float zr){return new PartPose(x,y,z,xr,yr,zr);}}''')
 write(t,'net/minecraft/client/model/geom/ModelPart.java','''package net.minecraft.client.model.geom;import java.util.*;import java.util.stream.*;public class ModelPart{public float x,y,z,xRot,yRot,zRot,xScale=1,yScale=1,zScale=1;public boolean visible=true;public final Map<String,ModelPart> children=new LinkedHashMap<>();public final List<float[]> cubes;private final PartPose original;public ModelPart(PartPose pose,List<float[]> cubes){original=pose;this.cubes=cubes;resetPose();}public void resetPose(){x=original.x();y=original.y();z=original.z();xRot=original.xr();yRot=original.yr();zRot=original.zr();xScale=yScale=zScale=1;}public ModelPart getChild(String name){if(!children.containsKey(name))throw new AssertionError("Missing rig joint: "+name);return children.get(name);}public boolean hasChild(String name){return children.containsKey(name);}public Stream<ModelPart> getAllParts(){return Stream.concat(Stream.of(this),children.values().stream().flatMap(ModelPart::getAllParts));}}''')
 write(t,'net/minecraft/client/model/geom/builders/CubeListBuilder.java','''package net.minecraft.client.model.geom.builders;import java.util.*;public class CubeListBuilder{public final List<float[]> cubes=new ArrayList<>();private int u,v;public static CubeListBuilder create(){return new CubeListBuilder();}public CubeListBuilder texOffs(int u,int v){this.u=u;this.v=v;return this;}public CubeListBuilder addBox(float x,float y,float z,float w,float h,float d){if(w<=0||h<=0||d<=0||u+2*(w+d)>64||v+h+d>128)throw new AssertionError("Invalid cube or UV bounds");cubes.add(new float[]{x,y,z,w,h,d});return this;}}''')
 write(t,'net/minecraft/client/model/geom/builders/PartDefinition.java','''package net.minecraft.client.model.geom.builders;import net.minecraft.client.model.geom.*;import java.util.*;public class PartDefinition{public final Map<String,PartDefinition> children=new LinkedHashMap<>();private CubeListBuilder cubes;private PartPose pose;public PartDefinition(){this(CubeListBuilder.create(),PartPose.ZERO);}public PartDefinition(CubeListBuilder cubes,PartPose pose){this.cubes=cubes;this.pose=pose;}public PartDefinition addOrReplaceChild(String name,CubeListBuilder c,PartPose p){var result=new PartDefinition(c,p);children.put(name,result);return result;}public PartDefinition getChild(String n){return children.get(n);}public ModelPart bake(){var r=new ModelPart(pose,cubes.cubes);children.forEach((k,v)->r.children.put(k,v.bake()));return r;}}''')
 for name in ['CreatureRig','CreatureMotion','BeastRig']:
  source=ROOT/f'src/main/java/com/shadowslave/client/{name}.java';write(t,f'com/shadowslave/client/{name}.java',source.read_text())
 text=(ROOT/'src/main/java/com/shadowslave/entity/CreatureEcology.java').read_text()
 species=re.findall(r's\(\s*"([a-z_]+)",\s*"([^"]+)",\s*(\d+),\s*(\d+),\s*(\d+),',text)
 entries=',\n'.join('new Spec("%s","%s",%s,%s)'%(id,name,family,cores) for id,name,rank,cores,family in species)
 entries+=',\n'+',\n'.join('new Spec("%s","%s",%d,4)'%(id,name,i) for i,(id,name) in enumerate(zip(['dragon','wolf','leviathan','colossus','stag','griffin','wyvern'],['Cinder Dragon','Dread Wolf Form','Tide Leviathan','Iron Colossus','Worldroot Stag','Mirror Griffin','Astral Wyvern'])))
 code='''import com.shadowslave.client.CreatureRig;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import java.util.*;import java.nio.file.*;
public class RigHarness{record Spec(String id,String name,int family,int cores){}static int count;static String dump(ModelPart p){StringBuilder s=new StringBuilder("{\\\"pose\\\":["+p.x+","+p.y+","+p.z+","+p.xRot+","+p.yRot+","+p.zRot+"],\\\"cubes\\\":[");for(int i=0;i<p.cubes.size();i++){if(i>0)s.append(',');s.append(Arrays.toString(p.cubes.get(i)));}s.append("],\\\"children\\\":{");boolean comma=false;for(var e:p.children.entrySet()){if(comma)s.append(',');comma=true;s.append("\\\"").append(e.getKey()).append("\\\":").append(dump(e.getValue()));}return s.append("}}").toString();}
public static void main(String[] args)throws Exception{Spec[] all={ENTRIES};StringBuilder json=new StringBuilder("[");Set<String> signatures=new HashSet<>();int cubes=0;
for(int n=0;n<all.length;n++){var spec=all[n];var parent=new PartDefinition();var rig=CreatureRig.build(parent,"rig",spec.id,spec.family,spec.cores).bake();
String signature=dump(rig);if(n<32&&!signatures.add(signature))throw new AssertionError("Identical species geometry: "+spec.id);
for(var p:rig.getAllParts().toList())cubes+=p.cubes.size();
if(n>0)json.append(',');json.append("{\\\"id\\\":\\\"").append(spec.id).append("\\\",\\\"name\\\":\\\"").append(spec.name).append("\\\",\\\"family\\\":").append(spec.family).append(",\\\"rig\\\":").append(signature).append('}');
for(boolean charging:new boolean[]{false,true})for(boolean flying:new boolean[]{false,true})for(float hit:new float[]{0,.5f,1})for(float age:new float[]{0,75,300}){rig.getAllParts().forEach(ModelPart::resetPose);CreatureRig.animate(rig,spec.id,12,.9f,age,34,-22,hit,charging,flying);for(var p:rig.getAllParts().toList()){for(float v:new float[]{p.x,p.y,p.z,p.xRot,p.yRot,p.zRot,p.xScale,p.yScale,p.zScale})if(!Float.isFinite(v))throw new AssertionError("Nonfinite pose");count++;}}
}json.append(']');if(args.length>0)Files.writeString(Path.of(args[0]),json.toString());System.out.println("PASS: "+all.length+" articulated rigs, "+cubes+" boxes inside 64x128 UV limits, "+count+" finite animated joint poses, 32 unique species geometry signatures. Geometry harness only; Minecraft bake still required.");}}
'''.replace('ENTRIES',entries)
 write(t,'RigHarness.java',code)
 subprocess.run(['javac','-d',str(t/'classes'),*[str(p) for p in t.rglob('*.java')]],check=True)
 subprocess.run(['java','-cp',str(t/'classes'),'RigHarness',*sys.argv[1:]],check=True)
